function message(key,language="es",data={}){
 if(!supported(language))return null;
 const forms=(DYNAMIC_MESSAGES[key]||DYNAMIC_MORE[key])?.[language];
 if(!forms)return null;
 const count=Number(data?.count);
 const form=typeof forms==="string"?forms:forms[count===1?"one":"other"];
 if(typeof form!=="string")return null;
 // Known, reviewed templates only; user-supplied values are inserted as text,
 // never markup or code.
 return form.replace(/\{(count|first|subjects|hours|time|date|person|subject|memory)\}/g,(_match,name)=>{
  const value=data?.[name];
  return value===undefined||value===null?"":String(value);
 });
}
